BEGIN IMMEDIATE;
PRAGMA user_version=1;
CREATE TABLE IF NOT EXISTS meta(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS quota_day(day TEXT PRIMARY KEY,hdf5_committed INTEGER NOT NULL DEFAULT 0,png_reserved INTEGER NOT NULL DEFAULT 0,png_committed INTEGER NOT NULL DEFAULT 0,aux_committed INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS artifact(id TEXT PRIMARY KEY,parent_id TEXT,path TEXT UNIQUE NOT NULL,day TEXT NOT NULL,start_utc_us INTEGER NOT NULL,created_utc_us INTEGER NOT NULL,cap INTEGER NOT NULL,png_cap INTEGER NOT NULL,state TEXT NOT NULL CHECK(state IN ('WRITING','READY','DELETE_PENDING','DELETED','QUARANTINED')),kind TEXT NOT NULL CHECK(kind IN ('h5','png')),size INTEGER NOT NULL DEFAULT 0,digest TEXT NOT NULL DEFAULT '',generation INTEGER NOT NULL DEFAULT 0,quicklook_enabled INTEGER NOT NULL,config_hash TEXT NOT NULL,session TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS job(artifact_id TEXT NOT NULL,destination TEXT NOT NULL,kind TEXT NOT NULL,status TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,next_utc_us INTEGER NOT NULL DEFAULT 0,error TEXT NOT NULL DEFAULT '',verified_utc_us INTEGER NOT NULL DEFAULT 0,digest TEXT NOT NULL DEFAULT '',PRIMARY KEY(artifact_id,destination,kind));
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY AUTOINCREMENT,utc_us INTEGER NOT NULL,artifact_id TEXT NOT NULL,start_utc_us INTEGER NOT NULL,size INTEGER NOT NULL,reason TEXT NOT NULL,upload_status TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS counters(key TEXT PRIMARY KEY,value INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS artifact_age ON artifact(state,start_utc_us);
COMMIT;
